        description: "Click an element in the browser. Accepts a CSS selector (#id, .class, button), xpath (//button[2]), or plain text (wrapped as text= automatically). A screenshot is saved after clicking.",
        args: {
          target: tool.schema.string().describe('e.g. "#submit", "a", //button[2], "Sign in"')
        },
        async execute(args) {
          const p = await ensurePage();
          const selector = resolveSelector(args.target);
